<?php
declare(strict_types=1);
require_once __DIR__.'/auth_check.php';require_once __DIR__.'/role_check.php';require_once __DIR__.'/db.php';
$id=max(1,(int)($_GET['id']??$_POST['id']??0));$role=(string)($_SESSION['role']??'');$user=(int)($_SESSION['user_id']??0);$repo=new QualitySystem\Repositories\ProgramManualRepository($conn);$manual=$repo->find($id,$role,$user);if(!$manual){http_response_code(404);exit('Program manual not found.');}$canUpdate=QualitySystem\Security\PermissionMatrix::allows($role,'program_manuals','update');
$targetConfig=['Course'=>['program_specification_courses','course_title','program_specification_id'],'PLO'=>['program_specification_plos','plo_text','program_specification_id'],'Staff'=>['program_staff','full_name',null],'Committee'=>['committees','committee_name',null]];
if($_SERVER['REQUEST_METHOD']==='POST'){if(!$canUpdate){http_response_code(403);exit('Access denied.');}$mappingId=(int)($_POST['mapping_id']??0);$status=(string)($_POST['status']??'');if(!in_array($status,['Suggested','Confirmed','Rejected','Missing'],true)){http_response_code(422);exit('Invalid mapping status.');}$find=$conn->prepare('SELECT * FROM program_manual_mappings WHERE id=:mapping AND program_manual_id=:manual');$find->execute([':mapping'=>$mappingId,':manual'=>$id]);$mapping=$find->fetch();if(!$mapping){http_response_code(404);exit('Mapping not found.');}$target=($_POST['target_record_id']??'')!==''?(int)$_POST['target_record_id']:null;if($target!==null){[$table,,$scope]=$targetConfig[$mapping['source_type']];$sql="SELECT COUNT(*) FROM $table WHERE id=:target".($scope?" AND $scope=:program":'');$check=$conn->prepare($sql);$params=[':target'=>$target];if($scope)$params[':program']=$manual['program_specification_id'];$check->execute($params);if(!(int)$check->fetchColumn()){http_response_code(422);exit('The selected target is not authorized for this program.');}}if($status==='Confirmed'&&$target===null){http_response_code(422);exit('Choose a target before confirming.');}$update=$conn->prepare('UPDATE program_manual_mappings SET target_record_id=:target,status=:status,match_method=:method,confidence=:confidence,reviewed_by_user_id=:user,reviewed_at=NOW() WHERE id=:mapping AND program_manual_id=:manual');$update->execute([':target'=>$target,':status'=>$status,':method'=>$target!==null?'manual_review':'none',':confidence'=>$status==='Confirmed'?100:0,':user'=>$user,':mapping'=>$mappingId,':manual'=>$id]);QualitySystem\Security\AuditLogger::record($conn,'program_manual_mapping_review','allowed','Program Manuals',['mapping_id'=>$mappingId,'status'=>$status],'program_manual',$id);header('Location: /program_manual_mapping_review.php?id='.$id.'&type='.urlencode((string)$mapping['source_type']));exit;}
$type=(string)($_GET['type']??'Course');if(!isset($targetConfig[$type]))$type='Course';$statusFilter=(string)($_GET['status']??'');$sourceSql=match($type){'Course'=>'SELECT id,course_code source_key,course_name source_label FROM program_manual_courses WHERE program_manual_id=:id','PLO'=>'SELECT id,plo_code source_key,description source_label FROM program_manual_plos WHERE program_manual_id=:id',default=>'SELECT id,source_key,source_label FROM program_manual_entities WHERE program_manual_id=:id AND entity_type=:entity'};$sources=$conn->prepare($sourceSql);$sourceParams=[':id'=>$id];if(in_array($type,['Staff','Committee'],true))$sourceParams[':entity']=$type;$sources->execute($sourceParams);$sourceMap=[];foreach($sources->fetchAll()as$s)$sourceMap[(int)$s['id']]=$s;
[$table,$label,$scope]=$targetConfig[$type];$targetSql="SELECT id,$label label FROM $table".($scope?" WHERE $scope=:program":'')." ORDER BY $label LIMIT 1000";$targets=$conn->prepare($targetSql);$targetParams=[];if($scope)$targetParams[':program']=$manual['program_specification_id'];$targets->execute($targetParams);$targetRows=$targets->fetchAll();$targetMap=array_column($targetRows,'label','id');$sql='SELECT * FROM program_manual_mappings WHERE program_manual_id=:id AND source_type=:type'.($statusFilter!==''?' AND status=:status':'').' ORDER BY FIELD(status,\'Missing\',\'Suggested\',\'Rejected\',\'Confirmed\'),confidence DESC,id';$stmt=$conn->prepare($sql);$params=[':id'=>$id,':type'=>$type];if($statusFilter!=='')$params[':status']=$statusFilter;$stmt->execute($params);$rows=$stmt->fetchAll();$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mapping review</title><link rel="stylesheet" href="/assets/style.css"><style>main{max-width:1300px;margin:auto;padding:1rem}.filters,.tabs{display:flex;gap:.6rem;flex-wrap:wrap}.card{border:1px solid #ccd3da;border-radius:10px;padding:1rem;margin:1rem 0}.meta{color:#536273}.actions{display:grid;grid-template-columns:2fr repeat(3,auto);gap:.5rem;align-items:end}select{width:100%}.Missing{border-left:6px solid #b42318}.Suggested{border-left:6px solid #d97706}.Confirmed{border-left:6px solid #16803a}.Rejected{border-left:6px solid #64748b}@media(max-width:800px){.actions{grid-template-columns:1fr}}</style></head><body><?php require __DIR__.'/nav.php';?><main><p><a href="/program_manual_automation.php?id=<?=$id?>">← Automation summary</a></p><h1>Mapping Review</h1><nav class="tabs" aria-label="Mapping types"><?php foreach(array_keys($targetConfig)as$t):?><a class="btn" href="?id=<?=$id?>&type=<?=$h($t)?>"><?=$h($t)?></a><?php endforeach;?></nav><form method="get" class="filters"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="type" value="<?=$h($type)?>"><label>Status <select name="status" onchange="this.form.submit()"><option value="">All</option><?php foreach(['Missing','Suggested','Confirmed','Rejected']as$s):?><option <?=$statusFilter===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></label></form><p><?=count($rows)?> <?=$h($type)?> mapping(s) displayed.</p><?php foreach($rows as$r):$source=$sourceMap[(int)$r['source_record_id']]??['source_key'=>'Unknown','source_label'=>'Source record unavailable'];?><article class="card <?=$h($r['status'])?>"><h2><?=$h($source['source_key'])?> — <?=$h($source['source_label'])?></h2><p class="meta">Status: <?=$h($r['status'])?> · Method: <?=$h($r['match_method'])?> · Confidence: <?=$h($r['confidence'])?>%<?php if($r['reviewed_at']):?> · Reviewed <?=$h($r['reviewed_at'])?><?php endif;?></p><form method="post" class="actions"><?=csrfField()?><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="mapping_id" value="<?=(int)$r['id']?>"><label>Target<select name="target_record_id"><option value="">No target</option><?php foreach($targetRows as$t):?><option value="<?=(int)$t['id']?>" <?=((int)$r['target_record_id']===(int)$t['id'])?'selected':''?>><?=$h($t['label'])?></option><?php endforeach;?></select></label><?php if($canUpdate):?><button name="status" value="Confirmed">Confirm</button><button name="status" value="Rejected">Reject</button><button name="status" value="Missing">Mark missing</button><?php endif;?></form></article><?php endforeach;?></main></body></html>
